/** 842 -> "842", 1280 -> "1.3k", 12400 -> "12k": a number that always fits a chip. */
export function compactCount(n: number, locale = 'en'): string {
  const v = Math.max(0, Math.floor(n));
  if (v < 1000) return String(v);
  return new Intl.NumberFormat(locale, { notation: 'compact', maximumFractionDigits: v < 10_000 ? 1 : 0 }).format(v).toLowerCase();
}

/** "bg_ember:0000" -> "bg_ember": the item a spend line was for. */
export const spendItemOf = (refId: string | null): string | null => (refId ? refId.split(':')[0] : null);

/** A name generated by provisioning, "Tera <Word> <3 digits>" (e.g. "Tera Curioso 482"). */
export const isGeneratedTeraName = (name: string): boolean => /^Tera\s+[\p{L}]+\s+\d{3}$/u.test(name.trim());
